function(container, apiUrl, tables) {
  // ============================================================
  // Data Initialization & State Management
  // ============================================================
  let currentWorker = null;
  let productivityData = [];
  let performanceData = [];
  let initialAssignmentData = [];
  let comparisonData = [];
  let chartInstances = {};

  const filterState = {
    period: 'month',
    startDate: null,
    endDate: null,
    workType: ''
  };

  // ============================================================
  // Utility Functions
  // ============================================================
  function getDateRange(period) {
    const today = new Date();
    let start, end = new Date(today);

    switch(period) {
      case 'today':
        start = new Date(today);
        break;
      case 'week':
        start = new Date(today);
        start.setDate(today.getDate() - 7);
        break;
      case 'month':
        start = new Date(today);
        start.setDate(1);
        break;
      case 'custom':
        start = filterState.startDate ? new Date(filterState.startDate) : new Date(today.getFullYear(), today.getMonth(), 1);
        end = filterState.endDate ? new Date(filterState.endDate) : today;
        break;
      default:
        start = new Date(today);
        start.setDate(today.getDate() - 30);
    }

    return { start, end };
  }

  function formatDate(date) {
    if (!date) return '—';
    const d = new Date(date);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  function getProficiencyLevel(productivity) {
    if (productivity >= 95) return 'エキスパート';
    if (productivity >= 85) return '上級';
    if (productivity >= 70) return '中級';
    return '初級';
  }

  function getProficiencyColor(level) {
    switch(level) {
      case 'エキスパート': return '#10b981';
      case '上級': return '#3b82f6';
      case '中級': return '#f59e0b';
      case '初級': return '#ef4444';
      default: return '#6b7280';
    }
  }

  // ============================================================
  // Data Fetching & Aggregation
  // ============================================================
  async function loadData() {
    try {
      // Fetch productivity data
      const prodData = await window.aivicApi.list(0); // 生産性データテーブル
      productivityData = prodData || [];

      // Fetch performance records
      const perfData = await window.aivicApi.list(1); // 実績記録テーブル
      performanceData = perfData || [];

      // Fetch initial assignments
      const initData = await window.aivicApi.list(2); // 初期割当テーブル
      initialAssignmentData = initData || [];

      // Fetch placement plans
      const placementData = await window.aivicApi.list(3); // 配置計画テーブル
      comparisonData = placementData || [];

      renderWorkerCards();
      updateCharts();
      updateComparisonTable();
      updateDetailPanels();
    } catch (error) {
      console.error('Data loading error:', error);
    }
  }

  // ============================================================
  // Worker Cards Rendering
  // ============================================================
  function renderWorkerCards() {
    const container = container.querySelector('#worker-cards-container');
    if (!container) return;

    container.innerHTML = '';

    // Group productivity data by worker
    const workerMap = {};
    productivityData.forEach(record => {
      if (!workerMap[record.workerId]) {
        workerMap[record.workerId] = {
          workerId: record.workerId,
          workerName: record.workerName || 'Unknown',
          location: record.location || '—',
          records: []
        };
      }
      workerMap[record.workerId].records.push(record);
    });

    // Create cards for each worker
    Object.values(workerMap).slice(0, 8).forEach(worker => {
      const avgProductivity = worker.records.length > 0
        ? Math.round(worker.records.reduce((sum, r) => sum + (r.productivityRate || 0), 0) / worker.records.length)
        : 0;
      const avgQuality = worker.records.length > 0
        ? Math.round(worker.records.reduce((sum, r) => sum + (r.qualityScore || 0), 0) / worker.records.length)
        : 0;
      const proficiency = getProficiencyLevel(avgProductivity);
      const profColor = getProficiencyColor(proficiency);

      const card = document.createElement('div');
      card.className = 'card';
      card.style.cssText = `
        padding: 12px;
        background: var(--bg-card);
        border-radius: var(--radius-card);
        box-shadow: var(--shadow-card);
        border: 1px solid var(--border);
        cursor: pointer;
        transition: all var(--motion-duration);
      `;
      card.onmouseover = () => {
        card.style.boxShadow = '0 4px 12px rgba(31, 41, 55, 0.12)';
        card.style.transform = 'translateY(-2px)';
      };
      card.onmouseout = () => {
        card.style.boxShadow = 'var(--shadow-card)';
        card.style.transform = 'translateY(0)';
      };
      card.onclick = () => selectWorker(worker.workerId, worker);

      card.innerHTML = `
        <div style="font-size: 13px; font-weight: 600; color: var(--text); margin-bottom: 8px;">${worker.workerName}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px;">${worker.location}</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
          <div>
            <div style="font-size: 10px; color: var(--text-muted);">生産性</div>
            <div style="font-size: 14px; font-weight: 700; color: var(--primary);">${avgProductivity}%</div>
          </div>
          <div>
            <div style="font-size: 10px; color: var(--text-muted);">品質</div>
            <div style="font-size: 14px; font-weight: 700; color: #3b82f6;">${avgQuality}</div>
          </div>
        </div>
        <div style="padding: 6px 8px; background: ${profColor}20; border-radius: 4px; text-align: center;">
          <div style="font-size: 11px; font-weight: 600; color: ${profColor};">${proficiency}</div>
        </div>
      `;

      container.appendChild(card);
    });
  }

  function selectWorker(workerId, workerInfo) {
    currentWorker = { id: workerId, ...workerInfo };
    updateDetailPanels();
    updateCharts();
    updateComparisonTable();
  }

  // ============================================================
  // Chart Rendering
  // ============================================================
  function updateCharts() {
    if (!window.Chart) {
      console.warn('Chart.js not loaded');
      return;
    }

    // Filter data based on current worker and date range
    const { start, end } = getDateRange(filterState.period);
    let filteredData = productivityData;

    if (currentWorker) {
      filteredData = filteredData.filter(r => r.workerId === currentWorker.id);
    }

    filteredData = filteredData.filter(r => {
      const recordDate = new Date(r.workDate);
      return recordDate >= start && recordDate <= end;
    });

    // Sort by date
    filteredData.sort((a, b) => new Date(a.workDate) - new Date(b.workDate));

    // ========== Productivity Time Series Chart ==========
    const prodCtx = container.querySelector('#productivity-chart');
    if (prodCtx) {
      if (chartInstances.productivity) {
        chartInstances.productivity.destroy();
      }

      const labels = filteredData.map(r => formatDate(r.workDate));
      const productivityValues = filteredData.map(r => r.productivityRate || 0);
      const standardLine = filteredData.map(() => 80); // Standard productivity target

      chartInstances.productivity = new window.Chart(prodCtx, {
        type: 'line',
        data: {
          labels: labels,
          datasets: [
            {
              label: '実績生産性率',
              data: productivityValues,
              borderColor: '#f59e0b',
              backgroundColor: 'rgba(245, 158, 11, 0.08)',
              borderWidth: 2,
              fill: true,
              tension: 0.3,
              pointRadius: 4,
              pointBackgroundColor: '#f59e0b',
              pointBorderColor: '#fff',
              pointBorderWidth: 2
            },
            {
              label: '標準値（80%）',
              data: standardLine,
              borderColor: '#d1d5db',
              borderWidth: 1,
              borderDash: [5, 5],
              fill: false,
              pointRadius: 0,
              tension: 0
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              display: true,
              labels: {
                font: { size: 11 },
                color: '#6b7280',
                usePointStyle: true,
                padding: 12
              }
            }
          },
          scales: {
            y: {
              beginAtZero: true,
              max: 100,
              ticks: {
                font: { size: 11 },
                color: '#6b7280',
                callback: function(value) { return value + '%'; }
              },
              grid: {
                color: 'rgba(229, 221, 208, 0.3)',
                drawBorder: false
              }
            },
            x: {
              ticks: {
                font: { size: 10 },
                color: '#6b7280',
                maxRotation: 45,
                minRotation: 0
              },
              grid: {
                display: false,
                drawBorder: false
              }
            }
          }
        }
      });
    }

    // ========== Deviation Analysis Chart ==========
    const devCtx = container.querySelector('#deviation-chart');
    if (devCtx) {
      if (chartInstances.deviation) {
        chartInstances.deviation.destroy();
      }

      // Aggregate by week for deviation analysis
      const weeklyData = {};
      filteredData.forEach(r => {
        const date = new Date(r.workDate);
        const weekStart = new Date(date);
        weekStart.setDate(date.getDate() - date.getDay());
        const weekKey = weekStart.toISOString().split('T')[0];

        if (!weeklyData[weekKey]) {
          weeklyData[weekKey] = { expected: 0, actual: 0, count: 0 };
        }
        weeklyData[weekKey].expected += 80; // Standard expectation
        weeklyData[weekKey].actual += r.productivityRate || 0;
        weeklyData[weekKey].count += 1;
      });

      const weekLabels = Object.keys(weeklyData).sort();
      const expectedValues = weekLabels.map(k => Math.round(weeklyData[k].expected / weeklyData[k].count));
      const actualValues = weekLabels.map(k => Math.round(weeklyData[k].actual / weeklyData[k].count));

      chartInstances.deviation = new window.Chart(devCtx, {
        type: 'bar',
        data: {
          labels: weekLabels.map(d => formatDate(d)),
          datasets: [
            {
              label: '期待値',
              data: expectedValues,
              backgroundColor: 'rgba(219, 234, 254, 0.8)',
              borderColor: '#3b82f6',
              borderWidth: 1
            },
            {
              label: '実績値',
              data: actualValues,
              backgroundColor: 'rgba(254, 215, 170, 0.8)',
              borderColor: '#f59e0b',
              borderWidth: 1
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              display: true,
              labels: {
                font: { size: 11 },
                color: '#6b7280',
                padding: 12
              }
            }
          },
          scales: {
            y: {
              beginAtZero: true,
              max: 100,
              ticks: {
                font: { size: 11 },
                color: '#6b7280',
                callback: function(value) { return value + '%'; }
              },
              grid: {
                color: 'rgba(229, 221, 208, 0.3)',
                drawBorder: false
              }
            },
            x: {
              ticks: {
                font: { size: 10 },
                color: '#6b7280'
              },
              grid: {
                display: false,
                drawBorder: false
              }
            }
          }
        }
      });
    }
  }

  // ============================================================
  // Comparison Table Update
  // ============================================================
  function updateComparisonTable() {
    const tbody = container.querySelector('#comparison-tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    // Filter comparison data
    let filtered = comparisonData;
    if (currentWorker) {
      filtered = filtered.filter(r => r.workerId === currentWorker.id);
    }

    filtered.slice(0, 10).forEach(record => {
      const expected = record.expectedProductivity || 80;
      const actual = record.actualProductivity || 0;
      const diff = actual - expected;
      const diffPercent = Math.round((diff / expected) * 100);
      const diffColor = diff >= 0 ? '#10b981' : '#ef4444';

      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 8px 12px; color: var(--text); border-right: 1px solid var(--border);">${record.workerName || '—'}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${expected}%</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${actual}%</td>
        <td style="padding: 8px 12px; text-align: center; color: ${diffColor}; font-weight: 600; background: ${diffColor}15;">
          ${diff >= 0 ? '+' : ''}${diffPercent}%
        </td>
      `;
      tbody.appendChild(row);
    });

    if (filtered.length === 0) {
      const row = document.createElement('tr');
      row.innerHTML = `<td colspan="4" style="padding: 16px; text-align: center; color: var(--text-muted);">データなし</td>`;
      tbody.appendChild(row);
    }
  }

  // ============================================================
  // Detail Panels Update
  // ============================================================
  function updateDetailPanels() {
    if (!currentWorker) {
      // Reset panels
      container.querySelector('#initial-dept').textContent = '—';
      container.querySelector('#initial-process').textContent = '—';
      container.querySelector('#initial-start-date').textContent = '—';
      container.querySelector('#initial-target').textContent = '—';
      container.querySelector('#actual-work-time').textContent = '—';
      container.querySelector('#actual-completed').textContent = '—';
      container.querySelector('#actual-productivity').textContent = '—';
      container.querySelector('#actual-quality').textContent = '—';
      container.querySelector('#proficiency-badge').textContent = '—';
      container.querySelector('#quality-alert').style.display = 'none';
      return;
    }

    // Initial Assignment Panel
    const assignment = initialAssignmentData.find(a => a.workerId === currentWorker.id);
    if (assignment) {
      container.querySelector('#initial-dept').textContent = assignment.department || '—';
      container.querySelector('#initial-process').textContent = assignment.process || '—';
      container.querySelector('#initial-start-date').textContent = formatDate(assignment.startDate);
      container.querySelector('#initial-target').textContent = (assignment.expectedProductivity || 80) + '%';
    }

    // Performance Panel (Latest Record)
    const latestPerf = performanceData
      .filter(p => p.workerId === currentWorker.id)
      .sort((a, b) => new Date(b.workDate) - new Date(a.workDate))[0];

    if (latestPerf) {
      container.querySelector('#actual-work-time').textContent = (latestPerf.workTimeMinutes || 0) + ' 分';
      container.querySelector('#actual-completed').textContent = (latestPerf.completedCount || 0) + ' 件';
      container.querySelector('#actual-productivity').textContent = (latestPerf.productivityRate || 0) + '%';
      container.querySelector('#actual-quality').textContent = (latestPerf.qualityScore || 0);
    }

    // Proficiency Level
    const avgProd = currentWorker.records && currentWorker.records.length > 0
      ? Math.round(currentWorker.records.reduce((sum, r) => sum + (r.productivityRate || 0), 0) / currentWorker.records.length)
      : 0;
    const profLevel = getProficiencyLevel(avgProd);
    const profColor = getProficiencyColor(profLevel);
    const badge = container.querySelector('#proficiency-badge');
    badge.textContent = profLevel;
    badge.style.background = profColor;

    // Quality Alert
    const recentQuality = performanceData
      .filter(p => p.workerId === currentWorker.id)
      .slice(-7)
      .map(p => p.qualityScore || 0);

    if (recentQuality.length > 0) {
      const avgQuality = Math.round(recentQuality.reduce((a, b) => a + b) / recentQuality.length);
      const alertEl = container.querySelector('#quality-alert');
      const msgEl = container.querySelector('#alert-message');

      if (avgQuality < 70) {
        alertEl.style.display = 'block';
        msgEl.textContent = `品質スコアが低下しています（直近7日平均: ${avgQuality}）`;
      } else {
        alertEl.style.display = 'none';
      }
    }
  }

  // ============================================================
  // Event Listeners
  // ============================================================
  const filterApplyBtn = container.querySelector('[data-testid="filter-apply-button"]');
  if (filterApplyBtn) {
    filterApplyBtn.addEventListener('click', () => {
      const periodSelect = container.querySelector('[data-testid="period-filter"]');
      const startInput = container.querySelector('[data-testid="start-date-input"]');
      const endInput = container.querySelector('[data-testid="end-date-input"]');
      const workTypeSelect = container.querySelector('[data-testid="work-type-filter"]');

      filterState.period = periodSelect.value || 'month';
      filterState.startDate = startInput.value;
      filterState.endDate = endInput.value;
      filterState.workType = workTypeSelect.value;

      updateCharts();
      updateComparisonTable();
    });
  }

  const periodSelect = container.querySelector('[data-testid="period-filter"]');
  if (periodSelect) {
    periodSelect.addEventListener('change', (e) => {
      filterState.period = e.target.value || 'month';
      if (e.target.value !== 'custom') {
        container.querySelector('[data-testid="start-date-input"]').value = '';
        container.querySelector('[data-testid="end-date-input"]').value = '';
      }
    });
  }

  // ============================================================
  // Initial Load
  // ============================================================
  loadData();
}

function(container, apiUrl, tables) {
