      startDate: '2025-01-20',
      currentProductivity: 68,
      proposedProductivity: 86
    }
  ];

  proposalData = mockProposals;

  // Render proposal list
  function renderProposalList(filter = '') {
    const tbody = container.querySelector('#proposal-list-tbody');
    tbody.innerHTML = '';

    proposalData
      .filter(p => !filter || p.workerName.includes(filter))
      .forEach(proposal => {
