        row.addEventListener('click', () => selectProposal(proposal.id));
        tbody.appendChild(row);
      });
  }

  // Select proposal and show detail
  function selectProposal(proposalId) {
    selectedProposalId = proposalId;
    const proposal = proposalData.find(p => p.id === proposalId);
    if (!proposal) return;

    // Update detail view
    container.querySelector('#detail-worker-name').textContent = proposal.workerName;
    container.querySelector('#detail-department').textContent = proposal.proposedDept;
    container.querySelector('#detail-process').textContent = '標準工程';
    container.querySelector('#detail-start-date').textContent = proposal.startDate;
    container.querySelector('#detail-productivity-target').textContent = `${proposal.productivityTarget}%`;
    container.querySelector('#detail-improvement-rate').textContent = `+${proposal.improvementRate}%`;
