      if (row.dataset.id === proposalId) {
        row.querySelectorAll('td').forEach(td => {
          td.style.color = '#fff';
        });
      } else {
        row.querySelectorAll('td').forEach(td => {
          td.style.color = 'var(--text)';
        });
      }
    });
  }

  // Draw productivity comparison chart
  function drawProductivityChart(proposal) {
    const canvas = container.querySelector('#productivity-chart');
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / 4;
    const maxValue = 100;

    // Background
    ctx.fillStyle = '#faf8f3';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Grid lines
    ctx.strokeStyle = '#e5ddd0';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // Y-axis labels
    ctx.fillStyle = '#6b7280';
    ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const value = (maxValue / 5) * i;
      const y = padding + chartHeight - (chartHeight / 5) * i;
      ctx.fillText(value + '%', padding - 10, y + 4);
    }

    // X-axis
    ctx.strokeStyle = '#1f2937';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // Y-axis
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.stroke();

    // Draw bars
    const data = [
      { label: '現在', value: proposal.currentProductivity, color: '#d97706' },
      { label: '提案後', value: proposal.proposedProductivity, color: '#f59e0b' }
    ];

    data.forEach((item, idx) => {
      const x = padding + barWidth * (idx + 0.5) - 20;
      const barHeight = (item.value / maxValue) * chartHeight;
      const y = canvas.height - padding - barHeight;

      ctx.fillStyle = item.color;
      ctx.fillRect(x, y, 40, barHeight);

      // Value label on bar
      ctx.fillStyle = '#1f2937';
      ctx.font = 'bold 13px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto';
      ctx.textAlign = 'center';
      ctx.fillText(item.value + '%', x + 20, y - 5);

      // X-axis label
      ctx.fillStyle = '#1f2937';
      ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto';
      ctx.fillText(item.label, x + 20, canvas.height - padding + 20);
    });

    // Title
    ctx.fillStyle = '#1f2937';
    ctx.font = 'bold 14px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto';
    ctx.textAlign = 'left';
    ctx.fillText(`${proposal.workerName} の生産性比較`, padding, 25);
  }

  // Event listeners
  container.querySelector('#worker-search').addEventListener('input', (e) => {
    renderProposalList(e.target.value);
  });

  container.querySelector('[data-testid="confirm-button"]').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').style.display = 'flex';
  });

  container.querySelector('[data-testid="approve-button"]').addEventListener('click', () => {
    container.querySelector('#approve-dialog').style.display = 'flex';
  });

  container.querySelector('[data-testid="reject-button"]').addEventListener('click', () => {
    container.querySelector('#reject-dialog').style.display = 'flex';
  });

  container.querySelector('[data-testid="execute-button"]').addEventListener('click', () => {
    if (!selectedProposalId) {
      alert('配置案を選択してください');
      return;
    }
    const proposal = proposalData.find(p => p.id === selectedProposalId);
    const summary = container.querySelector('#execute-summary');
    summary.innerHTML = `
      <strong>作業者:</strong> ${proposal.workerName}<br/>
      <strong>現在の部門:</strong> ${proposal.currentDept}<br/>
      <strong>配置先部門:</strong> ${proposal.proposedDept}<br/>
      <strong>期待生産性向上率:</strong> +${proposal.improvementRate}%<br/>
      <strong>配置開始予定日:</strong> ${proposal.startDate}
    `;
    const now = new Date();
    const isoString = now.toISOString().slice(0, 16);
    container.querySelector('#execute-datetime').value = isoString;
    container.querySelector('#execute-dialog').style.display = 'flex';
  });

  // Close dialogs on overlay click
  container.querySelectorAll('.modal-overlay').forEach(overlay => {
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) {
        overlay.style.display = 'none';
      }
    });
  });

  // Handle confirm submit
  window.handleConfirmSubmit = function() {
    const notes = container.querySelector('[data-testid="confirm-notes"]').value;
    console.log('Confirm notes:', notes);
    container.querySelector('#confirm-dialog').style.display = 'none';
    showSuccessMessage('配置案の確認が完了しました');
  };

  // Handle approve submit
  window.handleApproveSubmit = function() {
    const reason = container.querySelector('[data-testid="approve-reason"]').value;
    if (!reason.trim()) {
      alert('承認理由を入力してください');
      return;
    }
    console.log('Approve reason:', reason);
    container.querySelector('#approve-dialog').style.display = 'none';
    showSuccessMessage('配置案を承認しました');
  };

  // Handle reject submit
  window.handleRejectSubmit = function() {
    const reason = container.querySelector('[data-testid="reject-reason"]').value;
    if (!reason.trim()) {
      alert('却下理由を入力してください');
      return;
    }
    console.log('Reject reason:', reason);
    container.querySelector('#reject-dialog').style.display = 'none';
    showSuccessMessage('配置案を却下しました');
  };

  // Handle execute submit
  window.handleExecuteSubmit = function() {
    const datetime = container.querySelector('#execute-datetime').value;
    if (!datetime) {
      alert('実行日時を選択してください');
      return;
    }
    console.log('Execute datetime:', datetime);
    container.querySelector('#execute-dialog').style.display = 'none';
    showSuccessMessage('配置案を実行しました');
  };

  // Show success message
  function showSuccessMessage(message) {
    const msg = container.querySelector('#success-message');
    msg.textContent = message;
    msg.style.display = 'block';
    setTimeout(() => {
      msg.style.display = 'none';
    }, 3000);
  }

  // Initial render
  renderProposalList();
  if (proposalData.length > 0) {
    selectProposal(proposalData[0].id);
  }
}

function(container, apiUrl, tables) {
  const form = container.querySelector('#work-record-form');
  const errorMsg = container.querySelector('#error-message');
  const successMsg = container.querySelector('#success-message');
  const calcResult = container.querySelector('#calculation-result');
  const saveBtn = container.querySelector('[data-testid="save-button"]');

  // 本日の日付をデフォルト値に設定
  const dateInput = container.querySelector('[data-testid="work-date-input"]');
  const today = new Date().toISOString().split('T')[0];
  dateInput.value = today;

  // 時刻入力時に計算結果を更新
  const startTimeInput = container.querySelector('[data-testid="start-time-input"]');
  const endTimeInput = container.querySelector('[data-testid="end-time-input"]');
  const quantityInput = container.querySelector('[data-testid="quantity-input"]');

  function updateCalculations() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const quantity = parseInt(quantityInput.value) || 0;

    if (!startTime || !endTime) return;

    // 時刻をパース
    const [startHour, startMin] = startTime.split(':').map(Number);
    const [endHour, endMin] = endTime.split(':').map(Number);
    const startMinutes = startHour * 60 + startMin;
    const endMinutes = endHour * 60 + endMin;

    // 終了時刻が開始時刻より前の場合はエラーハイライト
    if (endMinutes <= startMinutes) {
      endTimeInput.style.borderColor = '#dc2626';
      calcResult.style.display = 'none';
      return;
    } else {
      endTimeInput.style.borderColor = 'rgba(229, 221, 208, 0.6)';
    }

    // 所要時間を計算
    const totalMinutes = endMinutes - startMinutes;
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    container.querySelector('#work-hours').textContent = hours;
    container.querySelector('#work-minutes').textContent = minutes;

    // 生産性率を計算（件/時間）
    if (totalMinutes > 0 && quantity > 0) {
      const productivityRate = Math.round((quantity / totalMinutes) * 60);
      container.querySelector('#productivity-rate').textContent = productivityRate;
      calcResult.style.display = 'block';
    } else {
      calcResult.style.display = 'none';
    }
  }

  startTimeInput.addEventListener('change', updateCalculations);
  endTimeInput.addEventListener('change', updateCalculations);
  quantityInput.addEventListener('input', updateCalculations);

  // フォーム送信処理
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errorMsg.style.display = 'none';
    successMsg.style.display = 'none';

    // フォームデータを取得
    const formData = new FormData(form);
    const workerId = formData.get('workerId');
    const departmentId = formData.get('departmentId');
    const taskTypeId = formData.get('taskTypeId');
    const workDate = formData.get('workDate');
    const startTime = formData.get('startTime');
    const endTime = formData.get('endTime');
    const quantity = parseInt(formData.get('quantity')) || 0;
    const unit = formData.get('unit');
    const qualityScore = parseInt(formData.get('qualityScore')) || 0;

    // バリデーション
    const errors = [];

    if (!workerId) errors.push('作業者を選択してください');
    if (!departmentId) errors.push('部門を選択してください');
    if (!taskTypeId) errors.push('作業タイプを選択してください');
    if (!workDate) errors.push('作業日付を入力してください');
    if (!startTime) errors.push('開始時刻を入力してください');
    if (!endTime) errors.push('終了時刻を入力してください');
    if (quantity <= 0) errors.push('実績数量は0より大きい値を入力してください');
    if (!unit) errors.push('単位を選択してください');
    if (qualityScore === 0) errors.push('品質評価を選択してください');

    // 時刻の妥当性チェック
    if (startTime && endTime) {
      const [startHour, startMin] = startTime.split(':').map(Number);
      const [endHour, endMin] = endTime.split(':').map(Number);
      const startMinutes = startHour * 60 + startMin;
      const endMinutes = endHour * 60 + endMin;
      if (endMinutes <= startMinutes) {
        errors.push('終了時刻は開始時刻より後の時刻を入力してください');
      }
    }

    if (errors.length > 0) {
      errorMsg.textContent = errors.join(' / ');
      errorMsg.style.display = 'block';
      return;
    }

    // 所要時間を計算
    const [startHour, startMin] = startTime.split(':').map(Number);
    const [endHour, endMin] = endTime.split(':').map(Number);
    const totalMinutes = (endHour * 60 + endMin) - (startHour * 60 + startMin);

    // 生産性率を計算
    const productivityRate = Math.round((quantity / totalMinutes) * 60);

    // 品質スコアを数値に変換（1-5を0-100に正規化）
    const qualityScoreNormalized = qualityScore * 20;

    // 保存データを構築
    const recordData = {
      workerId,
      departmentId,
      taskTypeId,
      workDate,
      startTime,
      endTime,
      quantity,
      unit,
      qualityScore: qualityScoreNormalized,
      workTimeMinutes: totalMinutes,
      productivityRate,
      createdAt: new Date().toISOString(),
    };

    // API経由で保存
    try {
      saveBtn.disabled = true;
      saveBtn.style.opacity = '0.6';

      // 実績記録テーブルに保存（tableIndex: 6 = 実績記録）
      const saved = await window.aivicApi.save(6, recordData);

      if (saved) {
        successMsg.style.display = 'block';
        form.reset();
        dateInput.value = today;
        calcResult.style.display = 'none';
        errorMsg.style.display = 'none';

        // 3秒後にメッセージを非表示
        setTimeout(() => {
          successMsg.style.display = 'none';
        }, 3000);
      } else {
        errorMsg.textContent = 'データの保存に失敗しました。もう一度お試しください。';
        errorMsg.style.display = 'block';
      }
    } catch (err) {
      errorMsg.textContent = 'エラーが発生しました: ' + (err.message || '不明なエラー');
      errorMsg.style.display = 'block';
    } finally {
      saveBtn.disabled = false;
      saveBtn.style.opacity = '1';
    }
  });

  // ボタンのホバー効果
  saveBtn.addEventListener('mouseover', () => {
    if (!saveBtn.disabled) {
      saveBtn.style.background = 'var(--primary-hover)';
    }
  });
  saveBtn.addEventListener('mouseout', () => {
    saveBtn.style.background = 'var(--primary)';
  });

  // ラジオボタンのビジュアルフィードバック
  const qualityLabels = container.querySelectorAll('label:has(input[name="qualityScore"])');
  qualityLabels.forEach(label => {
    const radio = label.querySelector('input[type="radio"]');
    radio.addEventListener('change', () => {
      qualityLabels.forEach(l => {
        const r = l.querySelector('input[type="radio"]');
        if (r.checked) {
          l.style.background = 'rgba(245, 158, 11, 0.12)';
          l.style.borderColor = 'var(--primary)';
        } else {
          l.style.background = 'var(--bg-main)';
          l.style.borderColor = 'rgba(229, 221, 208, 0.6)';
        }
      });
    });
  });
}
